import fs from 'node:fs';
import {createHash} from 'node:crypto';
import {totalUnits} from '../../../../../../../stock.mjs';
const target=new URL('../../../../../../../',import.meta.url);
const sample=JSON.parse(fs.readFileSync(new URL('stock.json',target),'utf8'));
const cases=[['current-stock',sample],['empty',[]],['duplicate-sku',[{sku:'pencil',quantity:8},{sku:'pencil',quantity:12}]],['string-quantity',[{sku:'notebook',quantity:'8'},{sku:'pencil',quantity:12}]],['negative-quantity',[{sku:'notebook',quantity:-1}]]];
const observations=cases.map(([name,input])=>{const actual=totalUnits(input);return {name,input,actual,type:typeof actual};});
const sourceRefs=['stock.mjs','stock.json'].map(path=>{const bytes=fs.readFileSync(new URL(path,target));return {path,bytes:bytes.length,sha256:createHash('sha256').update(bytes).digest('hex')};});
console.log(JSON.stringify({executedAt:new Date().toISOString(),node:process.version,sourceRefs,observations,meaning:'Actual imported source observations; not a new input validation contract or implementation PASS'},null,2));

import fs from "node:fs";
import path from "node:path";
import { spawn } from "node:child_process";
import { createHash } from "node:crypto";
import { fileURLToPath } from "node:url";
const [id, program, ...args] = process.argv.slice(2);
if (!/^[a-z0-9-]+$/.test(id) || !program) throw Error("capture id/program required");
const base = path.dirname(fileURLToPath(import.meta.url));
const directory = path.join(base, id);
fs.mkdirSync(directory);
const stdout = fs.openSync(path.join(directory, "stdout.txt"), "wx");
const stderr = fs.openSync(path.join(directory, "stderr.txt"), "wx");
const startedAt = new Date().toISOString();
const actual = program === "node" ? process.execPath : program;
let error = null;
const child = spawn(actual, args, { cwd: process.cwd(), windowsHide: true, shell: false, stdio: ["ignore", stdout, stderr] });
child.on("error", e => { error = e.message; });
child.on("close", (exitCode, signal) => {
 fs.closeSync(stdout); fs.closeSync(stderr);
 const ref = name => { const p = path.join(directory, name); const b = fs.readFileSync(p); return {path: path.relative(process.cwd(), p).replaceAll("\\","/"), bytes:b.length, sha256:createHash("sha256").update(b).digest("hex")}; };
 const record = {program:actual,args,cwd:process.cwd(),startedAt,finishedAt:new Date().toISOString(),exitCode,signal,error,node:process.version,platform:process.platform,stdout:ref("stdout.txt"),stderr:ref("stderr.txt")};
 fs.writeFileSync(path.join(directory,"command.json"),JSON.stringify(record,null,2)+"\n",{flag:"wx"});
 console.log(JSON.stringify(record));
 process.exitCode = exitCode ?? 1;
});

